    await check('wired bus preserves binary data through browser simulation',async()=>{const s={version:1,nodes:[n('i','input',0,0,{bits:4,value:10}),n('sp','splitter',250,0,{bits:4}),n('h','hub',500,0,{bits:4}),n('o','output',750,0,{bits:4})],wires:[wire('w1',end('i'),end('sp',0,'in')),wire('w2',end('h'),end('o',0,'in'))],definitions:{}};for(let i=0;i<4;i++)s.wires.push(wire('b'+i,end('sp',i),end('h',i,'in')));await importFile(s);assert.deepEqual(await page.evaluate(()=>LogicApp.getSimulation().outputs.o),[0,1,0,1]);assert.equal(await page.locator('.wire-line.bus').count(),2);});
    await check('bus width mismatch adapts in workbench',async()=>{const s=await get();s.nodes.at(-1).bits=1;await importFile(s);assert.deepEqual(await page.evaluate(()=>LogicApp.getSimulation().issues),[]);assert.equal(await page.locator('#sim-status').textContent(),'信号已稳定');});
    await check('help is keyboard-dismissable and describes wiring',async()=>{await page.locator('#help').click();assert.equal(await page.locator('#help-dialog').isVisible(),true);assert.match(await page.locator('#help-dialog').textContent(),/空白/);await page.keyboard.press('Escape');assert.equal(await page.locator('#help-dialog').isVisible(),false);});
    await check('Ctrl+A highlights all canvas components and Backspace deletes them in one undoable step',async()=>{const s=savedCircuit();s.wires.push(wire('free',{x:30,y:440},{x:180,y:440}));await importFile(s);await page.locator('#canvas').focus();await page.keyboard.press('Control+a');assert.equal(await page.locator('#node-layer .node.selected').count(),s.nodes.length);assert.match(await page.locator('#selection-status').textContent(),/4/);assert.equal(await page.locator('#wire-layer .wire.selected').count(),0);await page.keyboard.press('Backspace');let after=await get();assert.equal(after.nodes.length,0);assert.deepEqual(after.wires.map(w=>w.id),['free']);assert.deepEqual(after.definitions,s.definitions);await page.keyboard.press('Control+z');after=await get();assert.deepEqual(after.nodes,s.nodes);assert.deepEqual(after.wires,s.wires);await page.keyboard.press('Control+Shift+z');assert.equal((await get()).nodes.length,0);});
    await check('Delete and toolbar handle full selection; empty board and Escape are safe',async()=>{await importFile(circuit());await page.locator('#canvas').focus();await page.keyboard.press('Control+a');await page.keyboard.press('Escape');assert.equal(await page.locator('#node-layer .node.selected').count(),0);await page.keyboard.press('Backspace');assert.equal((await get()).nodes.length,4);await page.keyboard.press('Control+a');await page.keyboard.press('Delete');assert.equal((await get()).nodes.length,0);await page.keyboard.press('Control+a');await page.keyboard.press('Backspace');assert.equal((await get()).nodes.length,0);await page.locator('#undo').click();assert.equal((await get()).nodes.length,4);await page.locator('#canvas').focus();await page.keyboard.press('Control+a');await page.locator('#delete').click();assert.equal((await get()).nodes.length,0);await importFile(circuit());});
    await check('Ctrl+A and Backspace in labels or dialogs edit text without deleting circuit',async()=>{const p=await xy('n','body');await page.mouse.click(p.x,p.y);await page.locator('#prop-name').fill('测试名称');await page.locator('#prop-name').press('Control+a');await page.locator('#prop-name').press('Backspace');assert.equal(await page.locator('#prop-name').inputValue(),'');assert.equal((await get()).nodes.length,4);await page.locator('#package').click();await page.locator('#gate-name').fill('测试门');await page.locator('#gate-name').press('Control+a');await page.locator('#gate-name').press('Backspace');assert.equal((await get()).nodes.length,4);await page.keyboard.press('Escape');});
    await check('right mouse pans from blank and components without deleting',async()=>{for(const start of ['blank','node','port','toggle']){const s=circuit();s.wires=[wire('a',end('a'),end('n',0,'in'))];await importFile(s);const before=await get(),r=await page.locator('#canvas').boundingBox(),toggleBox=await page.locator('[data-toggle=a]').boundingBox();const p=start==='blank'?{x:r.x+70,y:r.y+500}:start==='node'?await xy('n','body'):start==='port'?await xy('n','in',0):{x:toggleBox.x+toggleBox.width/2,y:toggleBox.y+toggleBox.height/2};await drag(p,{x:p.x+95,y:p.y+65},'right');const after=await get();assert.deepEqual(after.nodes,before.nodes);assert.deepEqual(after.wires,before.wires);assert.equal(after.camera.x,before.camera.x+95);assert.equal(after.camera.y,before.camera.y+65);}});
    await check('right click input opens a menu and Delete removes that source and attached wire while preserving gates; undo restores it',async()=>{const s=circuit();s.wires=[wire('a',end('a'),end('n',0,'in')),wire('b',end('b'),end('n',1,'in')),wire('q',end('n'),end('o',0,'in')),wire('free',{x:70,y:470},{x:220,y:470})];await importFile(s);const before=await get(),p=await xy('a','body');await page.mouse.click(p.x,p.y,{button:'right'});assert.deepEqual((await get()).nodes,before.nodes);await page.locator('#context-delete').click();let after=await get();assert.deepEqual(after.nodes.map(n=>n.id),['b','n','o']);assert.deepEqual(after.wires.map(w=>w.id),['b','q','free']);await page.locator('#undo').click();after=await get();assert.deepEqual(after.nodes,before.nodes);assert.deepEqual(after.wires,before.wires);await page.locator('#redo').click();assert.equal((await get()).nodes.length,3);});
    await check('right click deletes only targeted wire even with another gate selected',async()=>{const s=circuit();s.wires=[wire('a',end('a'),end('n',0,'in')),wire('q',end('n'),end('o',0,'in'))];await importFile(s);const selected=await xy('b','body');await page.mouse.click(selected.x,selected.y);const before=await get(),ps=C.points(before.wires[0],before),r=await page.locator('#canvas').boundingBox(),x=(ps[0].x+ps[1].x)/2,y=(ps[0].y+ps[1].y)/2;await page.mouse.click(r.x+before.camera.x+x*before.camera.scale,r.y+before.camera.y+y*before.camera.scale,{button:'right'});const after=await get();assert.deepEqual(after.nodes,before.nodes);assert.deepEqual(after.wires.map(w=>w.id),['q']);await page.locator('#undo').click();assert.deepEqual((await get()).wires,before.wires);});
